INSERT INTO `courses` (`id`, `sku`, `name`, `slug`, `short_description`, `description`, `regular_price`, `sale_price`, `image_url`, `is_featured`, `is_published`, `position`) VALUES
  (1, 'ito-ai-ml', 'Artificial Intelligence & Machine Learning', 'artificial-intelligence-machine-learning', 'Hands-on AI/ML course covering model basics, practical datasets, and guided mini projects.', 'Hands-on AI/ML course covering model basics, practical datasets, and guided mini projects.', 1000.0, 750.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/04/AIML.webp', 0, 1, 0),
  (2, 'ito-python', 'Python Programming for Beginners', 'python-programming-for-beginners', 'Start coding with Python through live sessions, assignments, and mentor feedback.', 'Start coding with Python through live sessions, assignments, and mentor feedback.', 1000.0, 750.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/04/PythonCarouselCover.webp', 0, 1, 0),
  (3, 'ito-robotics', 'Robotics & Computational Thinking', 'robotics-computational-thinking', 'Build logic and automation skills with beginner robotics concepts and project work.', 'Build logic and automation skills with beginner robotics concepts and project work.', 1000.0, 750.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/04/RoboticsCarouselCover.webp', 0, 1, 0),
  (4, 'ito-algebra', 'Algebra I Foundation', 'algebra-i-foundation', 'Concept-to-application algebra training for middle and high school learners.', 'Concept-to-application algebra training for middle and high school learners.', 1000.0, 750.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/04/Algebra1Carousel.webp', 0, 1, 0),
  (5, 'ito-chess', 'Chess Strategy & Mind Sports', 'chess-strategy-mind-sports', 'Structured chess coaching focused on openings, tactics, and tournament readiness.', 'Structured chess coaching focused on openings, tactics, and tournament readiness.', 1000.0, 750.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/04/Chess.jpg', 0, 1, 0),
  (6, 'ito-violin', 'Violin/Viola Lessons for Beginners', 'violin-viola-lessons-for-beginners', 'Beginner-friendly violin and viola classes with technique drills and repertoire guidance.', 'Beginner-friendly violin and viola classes with technique drills and repertoire guidance.', 1000.0, 750.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/04/Violin.webp', 0, 1, 0),
  (7, 'ito-ap-physics', 'AP Physics Prep', 'ap-physics-prep', 'AP-aligned physics prep with concept boosters, timed practice, and exam strategy.', 'AP-aligned physics prep with concept boosters, timed practice, and exam strategy.', 1000.0, 750.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/04/App-Developement.jpg', 0, 1, 0),
  (8, 'ito-sat-math', 'SAT/PSAT Math Mastery', 'sat-psat-math-mastery', 'Targeted SAT and PSAT math preparation with diagnostics and score-improvement plans.', 'Targeted SAT and PSAT math preparation with diagnostics and score-improvement plans.', 1000.0, 750.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/04/AIMLCarouselCover.webp', 0, 1, 0),
  (9, NULL, 'Customized Online Guitar Lessons for Kids — Basics to Mastery', 'customized-online-guitar-lessons-for-kids-basics-to-mastery', 'Live guitar classes with expert mentors. Flexible timing, pay as you go, first demo class free.', 'Personalised online guitar coaching designed for young learners. Every class is one-on-one, paced to your child, and built around songs they love — so motivation stays high while technique builds steadily from the very first note.', 1500.0, 750.0, NULL, 0, 1, 0),
  (10, NULL, 'Online Piano &amp; Keyboard Classes for Kids and Beginners', 'online-piano-amp-keyboard-classes-for-kids-and-beginners', 'Structured 1:1 piano lessons with certified mentors. Learn at your pace, recital-ready.', 'A complete piano journey from first finger placement to confident two-hand playing. Lessons blend technique, theory and the pieces your child wants to play.', 1600.0, 800.0, NULL, 0, 1, 0),
  (11, NULL, 'Python Programming for Kids — Code Your First Projects', 'python-programming-for-kids-code-your-first-projects', 'Project-based live Python classes. Build games and apps from day one.', 'A hands-on introduction to real programming. Learners write actual Python, debug their own code, and finish each level with a project they can show off.', 1800.0, 900.0, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Python-1.jpg', 0, 1, 0),
  (12, NULL, 'Spoken English &amp; Confident Communication', 'spoken-english-amp-confident-communication', 'Live conversational English with personalised feedback. Speak fluently, fearlessly.', 'Move beyond grammar drills to real conversation. Every session is interactive, with structured feedback that targets fluency, pronunciation and confidence.', 1300.0, 650.0, NULL, 0, 1, 0),
  (13, NULL, 'Piano', 'piano', 'Live 1:1 and group Piano classes with expert mentors. Flexible scheduling, first demo free.', '<p>1. Convenience: You can attend classes from the comfort of your own home or any location with internet access. This eliminates the need for commuting, saving you time and money.</p><p>2. Flexibility: Online classes often offer flexible scheduling options, allowing you to choose the time that works best for you. This flexibility is especially beneficial for those with busy schedules or irregular working hours.</p><p>3. Access to Quality Instructors: Online platforms often have a wide selection of qualified instructors from around the world. This means you can find a teacher whose teaching style and expertise align with your learning goals.</p><p>4. Cost-effectiveness: Online classes can be more affordable than in-person lessons since they eliminate overhead costs associated with maintaining a physical location. Additionally, you can often find a variety of pricing options to suit your budget.</p><p>5. Variety of Resources: Online piano classes often come with a variety of supplementary resources such as video tutorials, practice exercises, and interactive learning tools, enhancing the overall learning experience.</p><p>6.Online Certifications: Opt for online examinations through various esteemed institutions and get certified for your skills.</p><p>At IndiaTutorsOnline, we believe that everyone has the potential to unlock their musical talents and start their journey of self-expression. IndiaTutorsOnline provides high-quality, accessible, and engaging online music classes for learners of all ages and skill levels.</p><p>We strive to break down barriers to learning and empower individuals from diverse backgrounds to pursue their passion for music, regardless of their geographical location, financial means, or previous experience.</p>', 600.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Piano-1.jpg', 0, 1, 0),
  (14, NULL, 'Guitar', 'guitar', 'Live 1:1 and group Guitar classes with expert mentors. Flexible scheduling, first demo free.', '<p>At IndiaTutorsOnline, we believe in the limitless potential within everyone to discover and develop their musical talents. We are dedicated to providing high-quality, accessible, and engaging online music classes that cater to learners of all ages and skill levels.</p><p>Our mission is to eliminate barriers to music education, empowering individuals from all walks of life to pursue their passion for music, no matter their location, financial situation, or prior experience.</p><p>Whether your dream is to master the piano, rock out on the guitar, or compose your own symphonies, IndiaTutorsOnline is here to help you bring your musical aspirations to life. Join us today and experience the joy of making music with IndiaTutorsOnline—where your journey to excellence begins.</p>', 600.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Guitar.jpg', 0, 1, 0),
  (15, NULL, 'Ukulele', 'ukulele', 'Live 1:1 and group Ukulele classes with expert mentors. Flexible scheduling, first demo free.', '<p>Accessible Across USA, UK, Europe, Australia, Singapore, Dubai, and More</p><p>Certificates of Completion / Participation Available</p><p>This program develops coordination, rhythm, listening skills, and musical creativity, while building confidence through performance and a love for music.</p><p>👉 Soprano Ukulele is strongly recommended for beginners</p><p>🎵 About Ukulele vs Guitar (Short Understanding)</p><p>The ukulele is a small, four-stringed instrument originally from Hawaii, traditionally strung with nylon strings and tuned G-C-E-A.</p><p>The guitar is a larger six-stringed instrument available in acoustic, classical, and electric variants, with a wider range of tones.</p><p>The ukulele offers a lighter, cheerful tone and is generally easier for young beginners, while the guitar provides a broader tonal range and greater repertoire depth.</p>', 600.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Ukulele.jpg', 0, 1, 0),
  (16, NULL, 'Keyboard', 'keyboard', 'Live 1:1 and group Keyboard classes with expert mentors. Flexible scheduling, first demo free.', '<p>1. Convenience: You can attend classes from the comfort of your own home or any location with internet access. This eliminates the need for commuting, saving you time and money.</p><p>2. Flexibility: Online classes often offer flexible scheduling options, allowing you to choose the time that works best for you. This flexibility is especially beneficial for those with busy schedules or irregular working hours.</p><p>3. Access to Quality Instructors: Online platforms often have a wide selection of qualified instructors from around the world. This means you can find a teacher whose teaching style and expertise align with your learning goals.</p><p>4. Cost-effectiveness: Online classes can be more affordable than in-person lessons since they eliminate overhead costs associated with maintaining a physical location. Additionally, you can often find a variety of pricing options to suit your budget.</p><p>5. Variety of Resources: Online keyboard classes often come with a variety of supplementary resources such as video tutorials, practice exercises, and interactive learning tools, enhancing the overall learning experience.</p><p>6.Online Certifications: Opt for online examinations through various esteemed institutions and get certified for your skills.</p><p>At IndiaTutorsOnline, we believe that everyone has the potential to unlock their musical talents and start their journey of self-expression. IndiaTutorsOnline provides high-quality, accessible, and engaging online music classes for learners of all ages and skill levels.</p><p>We strive to break down barriers to learning and empower individuals from diverse backgrounds to pursue their passion for music, regardless of their geographical location, financial means, or previous experience.</p>', 600.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Keyboard.jpg', 0, 1, 0)