  (17, NULL, 'Drums', 'drums', 'Live 1:1 and group Drums classes with expert mentors. Flexible scheduling, first demo free.', '', 600.0, NULL, NULL, 0, 1, 0),
  (18, NULL, 'Violin', 'violin', 'Live 1:1 and group Violin classes with expert mentors. Flexible scheduling, first demo free.', '', 1000.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Violin.jpg', 0, 1, 0),
  (19, NULL, 'Veena', 'veena', 'Live 1:1 and group Veena classes with expert mentors. Flexible scheduling, first demo free.', '', 600.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Veena.jpg', 0, 1, 0),
  (20, NULL, 'Cello', 'cello', 'Live 1:1 and group Cello classes with expert mentors. Flexible scheduling, first demo free.', '', 1500.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Cello.jpg', 0, 1, 0),
  (21, NULL, 'Viola', 'viola', 'Live 1:1 and group Viola classes with expert mentors. Flexible scheduling, first demo free.', '', 1000.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/AI-Prompting-1.jpg', 0, 1, 0),
  (22, NULL, 'Clarinet', 'clarinet', 'Live 1:1 and group Clarinet classes with expert mentors. Flexible scheduling, first demo free.', '<p>• Learn from home with proper posture and embouchure guidance• Flexible scheduling for students• Access to trained clarinet instructors• Focus on tone production, breath control, and articulation• Preparation for internationally recognized certifications</p><p>For Parents:This program develops breath control, discipline, coordination, listening skills, and musical expression, while building confidence through performance.</p><p>• Standard clarinet used by beginners and professionals• Balanced, warm tone• Widely used in classical, jazz, and band music• Recommended for most students</p><p>• Slightly longer than Bb clarinet• Warmer, darker tone• Common in orchestral repertoire• Used in advanced classical performance</p><p>• Larger instrument with deeper pitch• Rich, resonant sound• Used in orchestras, bands, and modern compositions• Requires more air support</p><p>• Smaller and higher-pitched• Bright, sharp tone• Used in orchestras and wind ensembles• More advanced and less common for beginners</p><p>👉 Bb Clarinet is strongly recommended for beginners</p><p>• Standard learning instrument• Easier fingering system• Comfortable size and handling• Used in ABRSM / Trinity exams</p>', 1500.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/clarinet.png', 0, 1, 0),
  (23, NULL, 'Tabla', 'tabla', 'Live 1:1 and group Tabla classes with expert mentors. Flexible scheduling, first demo free.', '<p>• Interactive and engaging live classes• 1:1 and group sessions available• Accessible globally (India, USA, UK, Europe, etc.)• Flexible scheduling• No contracts or hidden fees• Free demo class• Suitable for kids aged 6+• Focus on Hindustani classical rhythm system• Performance-based learning approach• Certificates of completion available</p><p>• Learn from home with proper hand technique and posture guidance• Flexible scheduling for students• Access to trained Indian classical tabla instructors• Focus on Bol, Taal, Layakari, and rhythmic clarity• Develop timing, coordination, and musical understanding</p><p>This program develops rhythm sense, coordination, discipline, concentration, and mathematical thinking, while enhancing creativity and confidence through structured rhythmic training and performance.</p><p>(Keep same as your file — no change needed)</p><p>The Tabla is the primary percussion instrument in Hindustani classical music, consisting of:</p><p>• Dayan (right drum) – tuned, melodic• Bayan (left drum) – bass, modulation</p><p>It is used in:• Classical music• Semi-classical (Bhajan, Ghazal)• Film &amp; fusion music</p><p>• Hindustani Classical Tradition (Guru-Shishya Parampara)• Institutional frameworks (Prayag Sangeet Samiti / Gandharva Mahavidyalaya)</p>', 600.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Tabla-1.jpg', 0, 1, 0),
  (24, NULL, 'Indian Flute', 'indian-flute', 'Live 1:1 and group Indian Flute classes with expert mentors. Flexible scheduling, first demo free.', '<p>For Parents:This program develops breath control, focus, discipline, and musical sensitivity, while improving cognitive coordination and listening skills.</p><p>What is the difference between Indian Bansuri Flute and Western Concert Flute?</p><p>The Bansuri is a bamboo flute without keys, used mainly in Indian classical music, focusing on expressive playing and improvisation.The Western Concert Flute is a metal, key-based instrument (Boehm system) used in Western classical, orchestral, and modern music.Bansuri relies on breath control and finger placement, while the Western flute allows faster, more precise note changes using keys.The sound of the Bansuri is warm and earthy, whereas the Western flute is bright and versatile.Bansuri learning is largely oral, while Western flute follows structured notation and exams (ABRSM, Trinity).Choose Bansuri for Indian classical expression, and Western flute for global music and certifications.</p><p>At IndiaTutorsOnline, we believe in the limitless potential within everyone to discover and develop their musical talents. We are dedicated to providing high-quality, accessible, and engaging online music classes that cater to learners of all ages and skill levels.</p><p>Our mission is to eliminate barriers to music education, empowering individuals from all walks of life to pursue their passion for music, no matter their location, financial situation, or prior experience.</p><p>Whether your dream is to master the piano, rock out on the Flute, or compose your own symphonies, IndiaTutorsOnline is here to help you bring your musical aspirations to life. Join us today and experience the joy of making music with IndiaTutorsOnline—where your journey to excellence begins.</p>', 600.0, NULL, NULL, 0, 1, 0),
  (25, NULL, 'Western Flute', 'western-flute', 'Live 1:1 and group Western Flute classes with expert mentors. Flexible scheduling, first demo free.', '<p>For Parents:This program develops breath control, focus, discipline, and musical sensitivity, while improving cognitive coordination and listening skills.</p><p>What is the difference between Indian Bansuri Flute and Western Concert Flute?</p><p>The Bansuri is a bamboo flute without keys, used mainly in Indian classical music, focusing on expressive playing and improvisation.The Western Concert Flute is a metal, key-based instrument (Boehm system) used in Western classical, orchestral, and modern music.Bansuri relies on breath control and finger placement, while the Western flute allows faster, more precise note changes using keys.The sound of the Bansuri is warm and earthy, whereas the Western flute is bright and versatile.Bansuri learning is largely oral, while Western flute follows structured notation and exams (ABRSM, Trinity).Choose Bansuri for Indian classical expression, and Western flute for global music and certifications.</p><p>At IndiaTutorsOnline, we believe in the limitless potential within everyone to discover and develop their musical talents. We are dedicated to providing high-quality, accessible, and engaging online music classes that cater to learners of all ages and skill levels.</p><p>Our mission is to eliminate barriers to music education, empowering individuals from all walks of life to pursue their passion for music, no matter their location, financial situation, or prior experience.</p><p>Whether your dream is to master the piano, rock out on the Flute, or compose your own symphonies, IndiaTutorsOnline is here to help you bring your musical aspirations to life. Join us today and experience the joy of making music with IndiaTutorsOnline—where your journey to excellence begins.</p>', 1000.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Sanskrit-1.webp', 0, 1, 0),
  (26, NULL, 'Saxophone', 'saxophone', 'Live 1:1 and group Saxophone classes with expert mentors. Flexible scheduling, first demo free.', '<p>For Parents:This program develops breath control, discipline, coordination, listening skills, and musical expression, while building confidence through performance.</p><p>2. Alto Saxophone (Most Recommended for Beginners)</p><p>👉 Alto Saxophone is strongly recommended for beginners</p><p>What is the difference between Indian Bansuri Flute and Western Concert Flute?</p><p>The Bansuri is a bamboo flute without keys, used mainly in Indian classical music, focusing on expressive playing and improvisation.The Western Concert Flute is a metal, key-based instrument (Boehm system) used in Western classical, orchestral, and modern music.Bansuri relies on breath control and finger placement, while the Western flute allows faster, more precise note changes using keys.The sound of the Bansuri is warm and earthy, whereas the Western flute is bright and versatile.Bansuri learning is largely oral, while Western flute follows structured notation and exams (ABRSM, Trinity).Choose Bansuri for Indian classical expression, and Western flute for global music and certifications.</p><p>At IndiaTutorsOnline, we believe in the limitless potential within everyone to discover and develop their musical talents. We are dedicated to providing high-quality, accessible, and engaging online music classes that cater to learners of all ages and skill levels.</p><p>Our mission is to eliminate barriers to music education, empowering individuals from all walks of life to pursue their passion for music, no matter their location, financial situation, or prior experience.</p><p>Whether your dream is to master the piano, rock out on the Saxophone, or compose your own symphonies, IndiaTutorsOnline is here to help you bring your musical aspirations to life. Join us today and experience the joy of making music with IndiaTutorsOnline—where your journey to excellence begins.</p>', 1000.0, NULL, 'https://indiatutorsonline.com/wp-content/uploads/2026/05/Saxophone.jpg', 0, 1, 0),
