-- IndiaTutors Online — Phase 1 database
-- Import this in phpMyAdmin: Databases tab → create `indiatutors` → Import → choose this file
-- OR: paste directly into phpMyAdmin's SQL tab after selecting the `indiatutors` database

CREATE DATABASE IF NOT EXISTS `indiatutors` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `indiatutors`;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `category_course`;
DROP TABLE IF EXISTS `courses`;
DROP TABLE IF EXISTS `categories`;
DROP TABLE IF EXISTS `demo_requests`;
DROP TABLE IF EXISTS `contact_messages`;
SET FOREIGN_KEY_CHECKS = 1;


-- ================================================================
-- SCHEMA
-- ================================================================

CREATE TABLE `categories` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `parent_id` BIGINT UNSIGNED NULL,
  `image_url` VARCHAR(500) NULL,
  `description` TEXT NULL,
  `position` INT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `categories_slug_unique` (`slug`),
  KEY `categories_parent_id_index` (`parent_id`),
  CONSTRAINT `categories_parent_id_foreign` FOREIGN KEY (`parent_id`)
    REFERENCES `categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `courses` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `sku` VARCHAR(120) NULL,
  `name` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `short_description` TEXT NULL,
  `description` LONGTEXT NULL,
  `regular_price` DECIMAL(10,2) NOT NULL DEFAULT 0,
  `sale_price` DECIMAL(10,2) NULL,
  `image_url` VARCHAR(500) NULL,
  `is_featured` TINYINT(1) NOT NULL DEFAULT 0,
  `is_published` TINYINT(1) NOT NULL DEFAULT 1,
  `position` INT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `courses_slug_unique` (`slug`),
  UNIQUE KEY `courses_sku_unique` (`sku`),
  KEY `courses_is_published_index` (`is_published`),
  KEY `courses_is_featured_index` (`is_featured`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `category_course` (
  `category_id` BIGINT UNSIGNED NOT NULL,
  `course_id` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`category_id`,`course_id`),
  KEY `category_course_course_id_foreign` (`course_id`),
  CONSTRAINT `category_course_category_id_foreign` FOREIGN KEY (`category_id`)
    REFERENCES `categories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `category_course_course_id_foreign` FOREIGN KEY (`course_id`)
    REFERENCES `courses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `demo_requests` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(120) NOT NULL,
  `email` VARCHAR(180) NOT NULL,
  `phone_country_code` VARCHAR(6) NOT NULL DEFAULT '+91',
  `phone` VARCHAR(20) NOT NULL,
  `subject` VARCHAR(120) NULL,
  `grade` VARCHAR(40) NULL,
  `board` VARCHAR(20) NULL,
  `mode` VARCHAR(20) NULL,
  `city` VARCHAR(80) NULL,
  `country` VARCHAR(80) NOT NULL DEFAULT 'India',
  `timezone` VARCHAR(60) NULL,
  `message` TEXT NULL,
  `whatsapp_consent` TINYINT(1) NOT NULL DEFAULT 0,
  `marketing_consent` TINYINT(1) NOT NULL DEFAULT 0,
  `course_id` BIGINT UNSIGNED NULL,
  `status` VARCHAR(20) NOT NULL DEFAULT 'new',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `demo_requests_status_index` (`status`),
  KEY `demo_requests_created_at_index` (`created_at`),
  KEY `demo_requests_course_id_foreign` (`course_id`),
  CONSTRAINT `demo_requests_course_id_foreign` FOREIGN KEY (`course_id`)
    REFERENCES `courses` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `contact_messages` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(120) NOT NULL,
  `email` VARCHAR(180) NOT NULL,
  `phone` VARCHAR(20) NULL,
  `subject` VARCHAR(200) NULL,
  `message` TEXT NOT NULL,
  `status` VARCHAR(20) NOT NULL DEFAULT 'new',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

